#!/usr/bin/env python3
"""CSV Insights - dependency-free command-line analytics tool."""

import csv
import io
import json
import sys
from decimal import Decimal, InvalidOperation


class CsvError(Exception):
    """User-facing error that should exit non-zero with a message."""


def parse_args(argv):
    """Parse command-line arguments into a config dict.

    Supported flags:
      --where COLUMN=VALUE  (repeatable, AND-combined, exact string match)
      --group-by COLUMN
      --sum COLUMN          (repeatable)
      --avg COLUMN          (repeatable)
      --output json|csv     (default json)
    """
    config = {
        "input": None,
        "where": [],
        "group_by": None,
        "sum": [],
        "avg": [],
        "output": "json",
    }

    if not argv:
        raise CsvError("missing INPUT.csv argument")

    # Positional input file
    config["input"] = argv[0]
    rest = argv[1:]

    i = 0
    while i < len(rest):
        arg = rest[i]
        if arg == "--where":
            if i + 1 >= len(rest):
                raise CsvError("--where requires a COLUMN=VALUE argument")
            value = rest[i + 1]
            if "=" not in value:
                raise CsvError(
                    f"malformed --where filter {value!r}: expected COLUMN=VALUE"
                )
            col, _, val = value.partition("=")
            if col == "":
                raise CsvError(
                    f"malformed --where filter {value!r}: empty column name"
                )
            config["where"].append((col, val))
            i += 2
        elif arg == "--group-by":
            if i + 1 >= len(rest):
                raise CsvError("--group-by requires a COLUMN argument")
            if config["group_by"] is not None:
                raise CsvError("--group-by may only be specified once")
            config["group_by"] = rest[i + 1]
            i += 2
        elif arg == "--sum":
            if i + 1 >= len(rest):
                raise CsvError("--sum requires a COLUMN argument")
            config["sum"].append(rest[i + 1])
            i += 2
        elif arg == "--avg":
            if i + 1 >= len(rest):
                raise CsvError("--avg requires a COLUMN argument")
            config["avg"].append(rest[i + 1])
            i += 2
        elif arg == "--output":
            if i + 1 >= len(rest):
                raise CsvError("--output requires an argument (json|csv)")
            out = rest[i + 1]
            if out not in ("json", "csv"):
                raise CsvError(f"invalid --output {out!r}: expected json or csv")
            config["output"] = out
            i += 2
        else:
            raise CsvError(f"unknown argument {arg!r}")

    # Validation: --sum / --avg require --group-by
    if (config["sum"] or config["avg"]) and config["group_by"] is None:
        raise CsvError("--sum and --avg require --group-by")

    return config


def read_csv(path):
    """Read an RFC-4180-style CSV file.

    Returns (headers, rows) where headers is a list of unique non-empty
    strings and rows is a list of lists of strings. Raises CsvError on
    malformed input.
    """
    try:
        with open(path, "r", newline="", encoding="utf-8") as fh:
            content = fh.read()
    except FileNotFoundError:
        raise CsvError(f"input file not found: {path}")
    except OSError as exc:
        raise CsvError(f"could not read input file {path!r}: {exc}")

    if content == "":
        raise CsvError("input file is empty")

    reader = csv.reader(io.StringIO(content))
    try:
        rows = list(reader)
    except csv.Error as exc:
        raise CsvError(f"malformed CSV: {exc}")

    if not rows:
        raise CsvError("input file has no rows")

    headers = rows[0]
    if len(headers) == 0 or any(h == "" for h in headers):
        raise CsvError("headers must be non-empty")
    if len(set(headers)) != len(headers):
        raise CsvError("headers must be unique")

    width = len(headers)
    data = []
    for idx, raw_row in enumerate(rows[1:], start=2):
        if len(raw_row) != width:
            raise CsvError(
                f"row {idx} has {len(raw_row)} fields, expected {width}"
            )
        data.append(raw_row)

    return headers, data


def validate_columns(headers, config):
    """Ensure all referenced columns exist in headers."""
    header_set = set(headers)
    for col, _ in config["where"]:
        if col not in header_set:
            raise CsvError(f"unknown column in --where: {col!r}")
    if config["group_by"] is not None and config["group_by"] not in header_set:
        raise CsvError(f"unknown column in --group-by: {config['group_by']!r}")
    for col in config["sum"]:
        if col not in header_set:
            raise CsvError(f"unknown column in --sum: {col!r}")
    for col in config["avg"]:
        if col not in header_set:
            raise CsvError(f"unknown column in --avg: {col!r}")


def apply_filters(headers, rows, where):
    """Return rows matching all (column, value) filters (exact string match)."""
    if not where:
        return rows
    col_indices = []
    for col, val in where:
        col_indices.append((headers.index(col), val))
    out = []
    for row in rows:
        match = True
        for idx, val in col_indices:
            if row[idx] != val:
                match = False
                break
        if match:
            out.append(row)
    return out


def to_decimal(value, row_num, col_name):
    """Convert a string cell to Decimal, raising CsvError on blank/invalid."""
    s = value.strip()
    if s == "":
        raise CsvError(
            f"blank numeric value in column {col_name!r} at row {row_num}"
        )
    try:
        return Decimal(s)
    except InvalidOperation:
        raise CsvError(
            f"invalid numeric value {value!r} in column {col_name!r} at row {row_num}"
        )


def aggregate(headers, rows, group_by, sum_cols, avg_cols):
    """Group rows by group_by column, computing sum/avg for requested columns.

    Returns (out_headers, out_rows) where out_rows are lists of strings.
    Groups are sorted lexicographically by group value.
    """
    gb_idx = headers.index(group_by)
    sum_idx = [(c, headers.index(c)) for c in sum_cols]
    avg_idx = [(c, headers.index(c)) for c in avg_cols]

    groups = {}
    for rnum, row in enumerate(rows, start=2):
        key = row[gb_idx]
        if key not in groups:
            groups[key] = {
                "count": 0,
                "sums": {c: Decimal(0) for c, _ in sum_idx},
                "avgs": {c: [] for c, _ in avg_idx},
            }
        g = groups[key]
        g["count"] += 1
        for c, idx in sum_idx:
            g["sums"][c] += to_decimal(row[idx], rnum, c)
        for c, idx in avg_idx:
            g["avgs"][c].append(to_decimal(row[idx], rnum, c))

    out_headers = [group_by]
    for c in sum_cols:
        out_headers.append(f"sum_{c}")
    for c in avg_cols:
        out_headers.append(f"avg_{c}")

    out_rows = []
    for key in sorted(groups.keys()):
        g = groups[key]
        row = [key]
        for c in sum_cols:
            row.append(format_decimal(g["sums"][c]))
        for c in avg_cols:
            total = sum(g["avgs"][c], Decimal(0))
            avg = total / Decimal(g["count"])
            row.append(format_decimal(avg))
        out_rows.append(row)

    return out_headers, out_rows


def format_decimal(value):
    """Format a Decimal as a plain, minimal decimal string.

    Examples: Decimal('3') -> '3', Decimal('2.5') -> '2.5',
    Decimal('0.010') -> '0.01'.
    """
    # Normalize removes trailing zeros and exponent, but may produce
    # scientific notation for very large/small numbers; use format to avoid
    # that and then strip trailing zeros after a decimal point.
    normalized = value.normalize()
    sign, digits, exponent = normalized.as_tuple()
    if exponent > 0:
        # Integer with trailing zeros; use plain string.
        s = format(value, "f")
    else:
        s = format(normalized, "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    if s == "-0":
        s = "0"
    return s


def emit_json(headers, rows):
    """Emit rows as a JSON array of objects."""
    out = []
    for row in rows:
        obj = {headers[i]: row[i] for i in range(len(headers))}
        out.append(obj)
    return json.dumps(out, indent=2, ensure_ascii=False)


def emit_csv(headers, rows):
    """Emit rows as RFC-4180 CSV with a header line."""
    buf = io.StringIO()
    writer = csv.writer(buf, quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n")
    writer.writerow(headers)
    writer.writerows(rows)
    return buf.getvalue()


def run(argv):
    """Execute the tool. Returns the output string. Raises CsvError on error."""
    config = parse_args(argv)
    headers, rows = read_csv(config["input"])
    validate_columns(headers, config)
    rows = apply_filters(headers, rows, config["where"])

    if config["group_by"] is not None:
        out_headers, out_rows = aggregate(
            headers,
            rows,
            config["group_by"],
            config["sum"],
            config["avg"],
        )
    else:
        out_headers = headers
        out_rows = rows

    if config["output"] == "json":
        return emit_json(out_headers, out_rows)
    return emit_csv(out_headers, out_rows)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        result = run(argv)
    except CsvError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 1
    sys.stdout.write(result)
    if not result.endswith("\n"):
        sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

